{"function":"() => {
const roots=[];
const walk=(root,path)=>{ root.querySelectorAll('*').forEach(el=>{ if(el.shadowRoot){ roots.push(path+' > '+el.tagName.toLowerCase()+(el.id?'#'+el.id:'')); walk(el.shadowRoot, path+' > '+el.tagName.toLowerCase()); } }); };
walk(document,'doc');
const iframes=[...document.querySelectorAll('iframe')].map(f=>f.src);
const custom=[...new Set([...document.querySelectorAll('*')].map(e=>e.tagName.toLowerCase()).filter(t=>t.includes('-')))];
return {roots, iframes, custom};
}"}

